parameters.jsCode:
// Junta la solicitud con la logistica extraida. El texto libre NO viaja mas alla.
const salida = [];
for (const item of $input.all()) {
  const s = $('Normalizar solicitud').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let logi;
  try {
    logi = JSON.parse(bruto);
  } catch (error) {
    logi = { servicio: 'por_determinar', preferencia: null, derivar_persona: true, posible_urgencia: false, confianza: 0 };
  }
  salida.push({
    json: {
      id: s.id,
      fecha_entrada: s.fecha_entrada,
      canal: s.canal,
      nombre: s.nombre,
      telefono: s.telefono,
      email: s.email,
      servicio: logi.servicio || s.servicio_form || 'por_determinar',
      preferencia: logi.preferencia || s.preferencia_form || '',
      derivar_persona: logi.derivar_persona === true || (s.texto || '').trim().length > 0,
      posible_urgencia: logi.posible_urgencia === true,
      confianza: Number(logi.confianza ?? 0),
      hay_texto_libre: (s.texto || '').trim().length > 0,
      estado: 'en_revision',
    },
  });
}
return salida;

